      "id": "modern-c03-l12-p01-011",
      "title": "グラッドストンの教育・労働組合と選挙法改正",
      "body": [
        "グラッドストンは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教育法</strong></span>を制定し、公立学校を増やして初等教育を確立したり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働組合法</strong></span>を制定して労働組合を合法にすると、さらに1884年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3回選挙法改正</strong></span>を実現して、<strong class=\"source-bold\">農業労働者や鉱山労働者</strong>に選挙権を拡大したよ。これで失業者（と女性）以外にはほとんど参政権が与えられたんだ（選挙法改正の一覧は<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.47</strong></span>の表を確認してね）。"
      ],
      "plainBody": [
        "グラッドストンは教育法を制定し、公立学校を増やして初等教育を確立したり、労働組合法を制定して労働組合を合法にすると、さらに1884年には第3回選挙法改正を実現して、農業労働者や鉱山労働者に選挙権を拡大したよ。これで失業者（と女性）以外にはほとんど参政権が与えられたんだ（選挙法改正の一覧は➡P.47の表を確認してね）。"
      ],
