      "id": "modern-c03-l12-p02-007",
      "title": "反議会・反共和政運動の結集",
      "body": [
        "すると、<strong class=\"source-bold\">政府に反対する勢力が次々とブーランジェのもとに結集</strong>して、<ruby>右翼<rt>うよく</rt></ruby>の王党派から<ruby>左翼<rt>さよく</rt></ruby>の急進派までも巻き込む<strong class=\"source-bold\">反議会主義、憲法改正</strong>を主張する反共和政運動になった。そして1889年にはパリの大衆運動が、<strong class=\"source-bold\">クーデタが起きる寸前</strong>まで盛り上がったよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>だ。"
      ],
      "plainBody": [
        "すると、政府に反対する勢力が次々とブーランジェのもとに結集して、右翼の王党派から左翼の急進派までも巻き込む反議会主義、憲法改正を主張する反共和政運動になった。そして1889年にはパリの大衆運動が、クーデタが起きる寸前まで盛り上がったよ。これがブーランジェ事件だ。"
      ],
