      "id": "modern-c03-l12-p02-015",
      "title": "軍部・教会と共和政擁護派の対立",
      "body": [
        "一方、偽装工作がバレた軍部が、メンツを保つために再審を<strong class=\"source-bold\">拒否</strong>すると、<ruby>右翼<rt>うよく</rt></ruby>の<strong class=\"source-bold\">国家主義者</strong>や、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ユダヤ主義</strong></span>をあおる<strong class=\"source-bold\">カトリック教会が軍部を支持</strong>したので、フランス国内では<strong class=\"source-bold\">共和政擁護派</strong>（ドレフュスを無罪として軍部を批判したグループ）と<strong class=\"source-bold\">反共和政派</strong>（軍部を支持して、ドレフュスを有罪にしようとしたグループ）が激しく対立したんだ。"
      ],
      "plainBody": [
        "一方、偽装工作がバレた軍部が、メンツを保つために再審を拒否すると、右翼の国家主義者や、反ユダヤ主義をあおるカトリック教会が軍部を支持したので、フランス国内では共和政擁護派（ドレフュスを無罪として軍部を批判したグループ）と反共和政派（軍部を支持して、ドレフュスを有罪にしようとしたグループ）が激しく対立したんだ。"
      ],
