      "title": "教会の政治介入と政教分離法",
      "body": [
        "それから一番問題だったのが、<strong class=\"source-bold\">カトリック教会の政治への<ruby>介入<rt>かいにゅう</rt></ruby></strong>だ。ずっと<strong class=\"source-bold\">保守勢力の中心</strong>は教会だったからね。そこで、1905年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政教分離法</strong></span>が制定されて、宗教に対する国の援助が一切排除され、教会の政治活動も禁止になった。"
      ],
