      "id": "modern-c03-l12-p02-024",
      "title": "フランスの孤立と1890年の国際情勢",
      "body": [
        "フランスは<strong class=\"source-bold\">ビスマルク外交によってヨーロッパでは孤立していた</strong>けど、<strong class=\"source-bold\">アジアやアフリカでは植民地を拡大</strong>して、イギリスに次ぐ植民地帝国を形成していたよね。そして、1890年には国際情勢が大きく変化するよ。ドイツで<strong class=\"source-bold\">ビスマルクが退陣</strong>して<strong class=\"source-bold\">ヴィルヘルム2世の親政</strong>になると、<strong class=\"source-bold\">ロシアとドイツの関係が急速に悪化</strong>した。"
      ],
      "plainBody": [
        "フランスはビスマルク外交によってヨーロッパでは孤立していたけど、アジアやアフリカでは植民地を拡大して、イギリスに次ぐ植民地帝国を形成していたよね。そして、1890年には国際情勢が大きく変化するよ。ドイツでビスマルクが退陣してヴィルヘルム2世の親政になると、ロシアとドイツの関係が急速に悪化した。"
      ],
