      "body": [
        "実は<strong class=\"source-bold\">フランスの銀行はむちゃくちゃお金を持ってる</strong>んだよ。フランスは革命で土地を得た中小農民が、いざという時のために貯金してるからね。ただ、<strong class=\"source-bold\">国内の工業発展は停滞気味</strong>……国内に投資先があまりなかったから、<strong class=\"source-bold\">海外に投資先を求めた</strong>んだね。"
      ],
