      "title": "ドイツ社会民主党とエルフルト綱領",
      "body": [
        "ビスマルク時代に弾圧されていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会主義労働者党</strong></span>は隠れて活動を続けていたんだけど、1890年に<strong class=\"source-bold\">社会主義者鎮圧法が廃止</strong>されると復活し、党の名前も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会民主党</strong></span>と変えて、正式に<strong class=\"source-bold\">マルクス主義を採用</strong>したよ（<strong class=\"source-bold\">エルフルト<ruby>綱領<rt>こうりょう</rt></ruby></strong>）。"
      ],
