      "title": "労働者の支援と第1インターナショナル",
      "body": [
        "ここで、<strong class=\"source-bold\">社会主義者が国際的に連携してつくった組織</strong>も確認しておこう。まず、1863年の<strong class=\"source-bold\">ポーランド反乱</strong>を各国の労働者たちが支援したことをきっかけに、1864年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span>を中心に<strong class=\"source-bold\">ロンドン</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1インターナショナル</strong></span>（<strong class=\"source-bold\">国際労働者協会を、のちにこう呼んだ</strong>）が結成されたよ。"
      ],
      "plainBody": [
        "ここで、社会主義者が国際的に連携してつくった組織も確認しておこう。まず、1863年のポーランド反乱を各国の労働者たちが支援したことをきっかけに、1864年にマルクスを中心にロンドンで第1インターナショナル（国際労働者協会を、のちにこう呼んだ）が結成されたよ。"
      ],
