      "id": "modern-c03-l12-p03-021",
      "title": "海軍の拡張とバグダード鉄道の敷設権",
      "body": [
        "ヴィルヘルム2世は「<strong class=\"source-bold\">ドイツの将来は海上にあり！</strong>」って宣言して、積極的な対外進出のために<strong class=\"source-bold\">海軍を拡張</strong>した。さらに、1899年には<strong class=\"source-bold\">トルコ</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード鉄道の<ruby>敷設<rt>ふせつ</rt></ruby>権</strong></span>を獲得し、<strong class=\"source-bold\">西アジアへの進出</strong>を狙ったよ。"
      ],
      "plainBody": [
        "ヴィルヘルム2世は「ドイツの将来は海上にあり！」って宣言して、積極的な対外進出のために海軍を拡張した。さらに、1899年にはトルコからバグダード鉄道の敷設権を獲得し、西アジアへの進出を狙ったよ。"
      ],
