      "id": "modern-c03-l12-p03-022",
      "title": "ベルリン・ビザンティウム・バグダードの3B政策",
      "body": [
        "これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3B政策</strong></span>」だ。<strong class=\"source-bold\">ドイツの</strong><strong class=\"source-bold\">首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン</strong></span>、トルコの首都イスタンブル</strong>（旧名が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビザンティウム</strong></span>）、そして<strong class=\"source-bold\">イラク</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード</strong></span>を鉄道で結んで、最終的には<strong class=\"source-bold\">ペルシア湾まで進出する</strong>のが目標だ。"
      ],
      "plainBody": [
        "これが「3B政策」だ。ドイツの首都ベルリン、トルコの首都イスタンブル（旧名がビザンティウム）、そしてイラクのバグダードを鉄道で結んで、最終的にはペルシア湾まで進出するのが目標だ。"
      ],
