        "かわって首相になった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ストルイピン</strong></span>は<strong class=\"source-bold\">革命運動を厳しく<ruby>弾圧<rt>だんあつ</rt></ruby>する反動政治</strong>を強行する一方で、表向きは「農民がきちんと自分の土地を持てるように」と言って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農村共同体（ミール）を解体</strong></span>した。これウラの意味だと、農民の反抗や革命の基盤になっているミールをなくしちゃえ！ってことなんだよね。"
