      "title": "貧困化する農民と富農クラーク",
      "body": [
        "ミールの解体で<strong class=\"source-bold\">貧乏な農民はさらに貧乏になった</strong>一方で、農村での助け合いから解放されて、少しは余裕があって「助けていたほう」の農民は豊かになった。こうして出現した<strong class=\"source-bold\"><ruby>富農<rt>ふのう</rt></ruby>をクラーク</strong>というんだ。"
      ],
      "plainBody": [
        "ミールの解体で貧乏な農民はさらに貧乏になった一方で、農村での助け合いから解放されて、少しは余裕があって「助けていたほう」の農民は豊かになった。こうして出現した富農をクラークというんだ。"
      ],
