      "title": "独占資本にも社会主義にも反対する中産階級",
      "body": [
        "中産階級も独占資本が経済を支配するのはイヤだったけど、<strong class=\"source-bold\">独占資本が強すぎると労働者が反発</strong>して「革命だぁ〜」とか言い出すかもしれない……。<strong class=\"source-bold\">中産階級は</strong>そこそこ財産を持ってるから<strong class=\"source-bold\">社会主義にはしたくない</strong>。"
      ],
