      "title": "プラット条項とキューバ保護国化",
      "body": [
        "そうはいっても、アメリカがそのままキューバを独立させるわけないよ……。1901年、アメリカはキューバの憲法に<strong class=\"source-bold\">プラット条項</strong>を無理やりぶち込んで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバを保護国化</strong></span>すると、<strong class=\"source-bold\">グアンタナモにアメリカ海軍の基地を建設</strong>した。やってることが、ひどすぎるよ……。"
      ],
      "plainBody": [
        "そうはいっても、アメリカがそのままキューバを独立させるわけないよ……。1901年、アメリカはキューバの憲法にプラット条項を無理やりぶち込んでキューバを保護国化すると、グアンタナモにアメリカ海軍の基地を建設した。やってることが、ひどすぎるよ……。"
      ],
