      "id": "modern-c03-l12-p05-025",
      "title": "リリウオカラニ退位とハワイ併合",
      "body": [
        "<strong class=\"source-bold\">米西戦争</strong>で<strong class=\"source-bold\">フィリピンとグアム</strong>を取っただけじゃなくて、アメリカは着々と<strong class=\"source-bold\">太平洋に進出</strong>する準備を進めてたんだよ。1893年、<strong class=\"source-bold\">親米市民のクーデタ</strong>によって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ</strong></span>の<strong class=\"source-bold\">カメハメハ朝</strong>の女王<strong class=\"source-bold\">リリウオカラニ</strong>を退位させていたアメリカは、<strong class=\"source-bold\">米西戦争中</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ併合</strong></span>を強行したんだ。"
      ],
