        "米西戦争でフィリピンとグアムを取っただけじゃなくて、アメリカは着々と太平洋に進出する準備を進めてたんだよ。1893年、親米市民のクーデタによって、ハワイのカメハメハ朝の女王リリウオカラニを退位させていたアメリカは、米西戦争中にハワイ併合を強行したんだ。"
