      "title": "ジョン＝ヘイの門戸開放宣言",
      "body": [
        "そこで、マッキンリー政権の<strong class=\"source-bold\">国務長官<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ヘイ</strong></span></strong>は、1899年と1900年の2回にわたって、<strong class=\"source-bold\">列強に対して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby>宣言</strong></span></strong>を発表したよ。まず1899年に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">門戸開放</strong></span>」「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">機会均等</strong></span>」を、そして1900年に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">領土<ruby>保全<rt>ほぜん</rt></ruby></strong></span>」を提唱した。"
      ],
      "plainBody": [
        "そこで、マッキンリー政権の国務長官ジョン＝ヘイは、1899年と1900年の2回にわたって、列強に対して門戸開放宣言を発表したよ。まず1899年に「門戸開放」「機会均等」を、そして1900年に「領土保全」を提唱した。"
      ],
