      "id": "modern-c03-l12-p05-030",
      "title": "3原則とアメリカのアジア外交",
      "body": [
        "これって要するに「アメリカも中国<ruby>市場<rt>しじょう</rt></ruby>に割り込みたい！ オレにも<ruby>儲<rt>もう</rt></ruby>けさせろ！」ってことだね。そして、<strong class=\"source-bold\">「門戸開放・機会均等・領土保全」</strong>の3原則が、第二次世界大戦まで<strong class=\"source-bold\">アメリカのアジア外交の基本原則</strong>になるんだよ。ここは、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第10回</strong></span>の中国分割のところとあわせて確認してね。"
      ],
      "plainBody": [
        "これって要するに「アメリカも中国市場に割り込みたい！ オレにも儲けさせろ！」ってことだね。そして、「門戸開放・機会均等・領土保全」の3原則が、第二次世界大戦までアメリカのアジア外交の基本原則になるんだよ。ここは、第10回の中国分割のところとあわせて確認してね。"
      ],
