      "id": "modern-c03-l12-p05-036",
      "title": "アメリカの大西洋・太平洋と海軍",
      "body": [
        "じゃあ、「棍棒」で何をするのかっていうと、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パナマ運河</strong></span>を建設したかったんだよ。<strong class=\"source-bold\">アメリカ</strong>って大陸国家だけど、<strong class=\"source-bold\">実は海洋国家</strong>だよね。<strong class=\"source-bold\">大西洋と太平洋に挟まれてる</strong>でしょ。だから、海軍も両方に置いとかなきゃいけない。"
      ],
