      "title": "ドミニカの関税管理権とニカラグア・ハイチ",
      "body": [
        "1905年には<strong class=\"source-bold\">ドミニカ</strong>から関税管理権を奪って事実上の保護国にしたり、さらに<strong class=\"source-bold\">ニカラグア</strong>や<strong class=\"source-bold\">ハイチ</strong>もたびたびアメリカの干渉を受けたよ。"
      ],
      "plainBody": [
        "1905年にはドミニカから関税管理権を奪って事実上の保護国にしたり、さらにニカラグアやハイチもたびたびアメリカの干渉を受けたよ。"
      ],
