      "id": "modern-c03-l12-p05-054",
      "title": "ディアスの独裁とアメリカへの従属",
      "body": [
        "その後メキシコでは、フランスとの戦いで活躍した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディアス</strong></span>将軍がクーデタで大統領となり、教会や軍部、大地主の特権を復活させて<strong class=\"source-bold\">独裁を強化</strong>し、<strong class=\"source-bold\">経済的にはアメリカと結んで権力を維持</strong>した。こうしてメキシコは、<strong class=\"source-bold\">アメリカへの従属</strong>を強めてしまったんだね。"
      ],
      "plainBody": [
        "その後メキシコでは、フランスとの戦いで活躍したディアス将軍がクーデタで大統領となり、教会や軍部、大地主の特権を復活させて独裁を強化し、経済的にはアメリカと結んで権力を維持した。こうしてメキシコは、アメリカへの従属を強めてしまったんだね。"
      ],
