export const sourcePages = {
  "215": "<h2>215</h2>\n<h3><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">帝国主義時代の欧米諸国</strong></span></h3>\n<p>今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">欧米諸国の国内問題を中心</strong></u>に見ていくよ。ヨーロッパ列強は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">帝国主義の時代に突入</strong></u>したんだけど、国内ではさまざまな矛盾が現れていたよ。さらに、新興国だった<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカ</strong></u>が、一気に<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">勢力を拡大</strong></u>するのもこの時代だよ！</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">イギリス ～自由党の改革と労働党の出現～</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">216〜218ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">フランス ～第三共和政の諸問題～</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">218〜221ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">ドイツ ～ドイツの発展と社会主義～</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">222〜224ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">ロシア ～ロシアの社会主義と第1次ロシア革命～</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">224〜228ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span></td><td><strong class=\"source-bold\">アメリカ合衆国 ～アメリカの帝国主義～</strong><br><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">228〜235ページ</span></td></tr></tbody></table></div>\n<blockquote><p>列強が世界分割をしていたころ、国内では何が起きていたんだろう？ キーワードは「社会主義」だよ</p></blockquote>\n<p><u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">独占資本の出現</strong></u>など、欧米では資本主義が発展した反面、労働者の生活はあまり豊かにはならなかった。こうした実態を解決しようとしたのが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">社会主義</strong></u>だよ。この時代、各国では<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">社会主義政党</strong></u>がつくられて、政治にも影響力を持つようになったんだ。一方、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカは世界1位の工業国</strong></u>になって、本格的に<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">対外進出</strong></u>を始めるよ。キーワードは「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>棍棒<rt>こんぼう</rt></ruby>外交</strong></u>」「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ドル外交</strong></u>」そして「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby>宣言</strong></u>」。各国の派手な<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">植民地獲得競争</strong></u>のウラで何が起きていたのか、しっかり確認してね。</p>\n<p>それじゃあ、帝国主義時代の欧米諸国の始まり〜。</p>",
  "216": "<h2>216</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <strong class=\"source-bold\">イギリス ～自由党の改革と労働党の出現～</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">下層労働者も選挙権を獲得！ 労働者の議会進出が始まった</strong></span></h4>\n<p>19世紀後半のイギリスは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディズレーリ</strong></span>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保守党</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グラッドストン</strong></span>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由党</strong></span>が交互に政権に就く二大政党制になってたよね。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保守党</strong></span>は<strong class=\"source-bold\">地主を中心</strong>とする金持ちの政党で、「ガンガン<strong class=\"source-bold\">植民地を増やそう！</strong>」っていう<strong class=\"source-bold\">大英国主義</strong>をとっていた。これは当時のイギリスが、増え続ける<strong class=\"source-bold\">貿易赤字を植民地への投資で穴埋め</strong>していたことが背景なんだ。</p>\n<p>1869年にアメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大陸横断鉄道</strong></span>開通と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河</strong></span>が完成すると、1870年代には植民地などから<strong class=\"source-bold\">安い農産物</strong>が大量に入ってきて、イギリスでは農業が大<ruby>不況<rt>ふきょう</rt></ruby>になった。さらに、新興国<strong class=\"source-bold\">アメリカやドイツの工業発展と保護貿易政策で輸出が減少</strong>して、貿易赤字が拡大していた。そしてドイツで発生した<ruby>恐慌<rt>きょうこう</rt></ruby>の影響からイギリスでも「<strong class=\"source-bold\">1873年の恐慌</strong>」が起き、<strong class=\"source-bold\">長い不況の時代</strong>に突入したんだ。ただこの時のイギリスを支えたのが、植民地や新興国への投資（<strong class=\"source-bold\">資本輸出</strong>）なんだ。イギリスは、「<strong class=\"source-bold\">世界の工場</strong>」<strong class=\"source-bold\">ではなくなった</strong>けど、金融で国際社会をリードする「<strong class=\"source-bold\">世界の銀行</strong>」として、<ruby>覇権<rt>はけん</rt></ruby>を維持したんだよ。</p>\n<p>でも、国内の<strong class=\"source-bold\">労働者の生活は厳しくなる</strong>。そこで、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由党</strong></span>は<strong class=\"source-bold\">国内改革を優先</strong>する<strong class=\"source-bold\">小英国主義</strong>を主張したんだ。グラッドストンは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">教育法</strong></span>を制定し、公立学校を増やして初等教育を確立したり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働組合法</strong></span>を制定して労働組合を合法にすると、さらに1884年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3回選挙法改正</strong></span>を実現して、<strong class=\"source-bold\">農業労働者や鉱山労働者</strong>に選挙権を拡大したよ。これで失業者（と女性）以外にはほとんど参政権が与えられたんだ（選挙法改正の一覧は<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.47</strong></span>の表を確認してね）。</p>\n<p>だから<strong class=\"source-bold\">労働者</strong>たちは、「選挙権をもらえたんだから、<strong class=\"source-bold\">自分たちの代表を議会に送ろう</strong>」って考えた。そうじゃないと自分たちの意見が政治に取り入れられないし、生活も良くならない！ ただ、議会に進出するには、仲間がいないと選挙で勝てない。そこで、イギリスでは<strong class=\"source-bold\">労働者が社会主義団体をつくり始めた</strong>んだ。</p>\n<p>ここで、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span>の文化史のところでやった「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス主義</strong></span>」<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.117</strong></span>を思い出してね。「絶対王政を倒す<strong class=\"source-bold\">ブルジョワ革命</strong>と、資本主義を倒す<strong class=\"source-bold\">社会主義革命</strong>という、<strong class=\"source-bold\">2回の革命をやると社会主義になる！</strong>」っていう考え方だ。マルクス主義は、今回いろんな国で出てくるから、もう一度思い出しておこう！</p>\n<p><strong class=\"source-bold\">イギリス</strong>はすでにピューリタン革命と名誉革命で絶対王政を倒しているから、<strong class=\"source-bold\">次の革命は社会主義革命</strong>ってことになる。この<strong class=\"source-bold\">マルクス主義</strong>の考え方をとっていたのが<strong class=\"source-bold\">社会民主連盟</strong>だよ。でも、イギリスではマルクス主義はあまり強くない。だって、すでに<strong class=\"source-bold\">議会主義が確立されている</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3回選挙法改正</strong></span>で労働者のほとんどが選挙権をもらっ</p>\n<blockquote><p>マルクス主義って「革命が目標」だよね。イギリスにはちょっと合わないよな</p></blockquote>",
  "217": "<h2>217</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イギリス ～自由党の改革と労働党の出現～</u></p>\n<p>てる。だから、<strong class=\"source-bold\">社会主義者の議会進出</strong>によって社会改革を実現するという「<strong class=\"source-bold\"><ruby>漸進<rt>ぜんしん</rt></ruby>的社会改革</strong>」を主張する団体のほうが強かったんだ。こうした団体は2つできたよ。</p>\n<p>一つは<strong class=\"source-bold\">知識人を主体</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フェビアン協会</strong></span>だ。指導者は社会学者の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウェッブ夫妻</strong></span>や劇作家の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーナード＝ショー</strong></span>。<strong class=\"source-bold\">本人たちは労働者じゃない</strong>けど、「議会を通じて社会主義に近づけていこう！」（これが「フェビアン社会主義」と呼ばれたんだ）っていう団体だ。もう一つが<strong class=\"source-bold\">ケア＝ハーディ</strong>を指導者とする<strong class=\"source-bold\">独立労働党</strong>。こっちは、実際に<strong class=\"source-bold\">労働者が議会に進出する</strong>ことで社会を変えていこうとする団体だよ。</p>\n<h4><strong class=\"source-bold\">〈イギリスの社会主義団体〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">社会民主連盟</strong>［1884改称］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> イギリス唯一の<strong class=\"source-bold\">マルクス主義</strong>による社会主義団体</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フェビアン協会</strong></span>［1884］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> 指導者：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウェッブ夫妻</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バーナード＝ショー</strong></span><br><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">知識人</strong>主体の社会主義団体<br><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">漸進的社会改革</strong>を主張（<strong class=\"source-bold\">議会進出による社会主義への移行</strong>）</td></tr><tr><td><strong class=\"source-bold\">独立労働党</strong>［1893］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> 指導者：<strong class=\"source-bold\">ケア＝ハーディ</strong><br><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">労働者の議会進出</strong>と社会主義の漸進的達成を目指した</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">団体が3つもあったら選挙で勝てない。労働者の政党として労働党ができた！</strong></span></h4>\n<p>こうして3つの政治団体ができたんだけど、ちょっと事件！ だって、「<strong class=\"source-bold\">このままだと選挙で勝てない</strong>」。イギリスは<strong class=\"source-bold\">小選挙区制</strong>だから、1つの選挙区で当選するのは1人。社会主義の団体3つからそれぞれ候補者を出すと、票が割れて1位になれないよ……。「だったら、<strong class=\"source-bold\">1コにまとめればいい</strong>！」。こうして、<strong class=\"source-bold\">独立労働党、フェビアン協会、社会民主連盟</strong>の3つの社会主義団体に65の労働組合の代表者を合わせて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働代表委員会</strong></span>が結成され、1906年の総選挙では29議席も獲得したよ。これが<strong class=\"source-bold\">事実上の労働党結成</strong>だ！</p>\n<p>ただ、労働代表委員会にも問題発生！ <strong class=\"source-bold\">社会民主連盟だけマルクス主義</strong>だよ。議会進出とマルクス主義って衝突するでしょ？ だって革命の目標は「政府も議会も<ruby>潰<rt>つぶ</rt></ruby>す」。てか、議会に自分がいるから自爆だよ。結局、<strong class=\"source-bold\">社会民主連盟は不参加</strong>となり、1906年、初代党首を<strong class=\"source-bold\">ケア＝ハーディ</strong>、初代委員長を<strong class=\"source-bold\">マクドナルド</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働党</strong></span>が正式に結成され、<strong class=\"source-bold\">議会進出による社会改革</strong>（漸進主義・合法主義）路線をとったよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">労働党の出現で労働者の影響力が強まり、改革が進んだ！</strong></span></h4>\n<p>労働党の出現は、イギリスの政治にも大きな影響を与えた。だって、保守党と自由党がどっちも過半数をとれなかった時には、労働党が味方したほうが政権に就けるんだよ。まあ、労働党が保守党に味方するとは思えないけど。でも、<strong class=\"source-bold\">自由党だって労働党にいい顔をしとかないと、いざという時に困る</strong>……。</p>\n<p>こうして、<strong class=\"source-bold\">自由党が労働者に有利な政策を打ち出した</strong>。1908年に成立した自由党</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "218": "<h2>218</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p>の<strong class=\"source-bold\">アスキス</strong>内閣では、失業中の労働者に対して生活保護をおこなう<strong class=\"source-bold\">国民保険法</strong>や、<strong class=\"source-bold\">予算や法律制定の際の下院の優先権</strong>を定めた<strong class=\"source-bold\">議会法【議院法】</strong>が制定された。議会法ができたのは、<strong class=\"source-bold\">上院が猛反対</strong>していた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アイルランド自治法</strong></span>を成立させるためだ。</p>\n<p>とはいっても、すぐには労働党政権はできない。<strong class=\"source-bold\">最初の労働党内閣</strong>ができるのは、<strong class=\"source-bold\">第一次世界大戦後</strong>だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <strong class=\"source-bold\">フランス ～第三共和政の諸問題～</strong></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">フランスの第三共和政</strong></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>】</strong>［1870〜71］</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>をドイツに<ruby>割譲<rt>かつじょう</rt></ruby> <span data-source-color=\"green\" style=\"color:#315837\">➡</span> <strong class=\"source-bold\">対独<ruby>復讐<rt>ふくしゅう</rt></ruby>心</strong>が高揚</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">第三共和政憲法</strong>制定［1875］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span> 共和派と王党派が議会内で対立</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>［1887〜89］ ……<strong class=\"source-bold\">対独復讐心</strong>が背景</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">対ドイツ強硬派</strong>の元陸相<strong class=\"source-bold\">ブーランジェ</strong>を中心とする反共和政運動</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドレフュス事件</strong></span>［1894〜99］ ……<strong class=\"source-bold\">対独復讐心</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ユダヤ主義</strong></span>が背景</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">ユダヤ人将校<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドレフュス</strong></span></strong>に対するスパイ容疑事件</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span> <strong class=\"source-bold\">共和政<ruby>擁護<rt>ようご</rt></ruby>派</strong>と<strong class=\"source-bold\">反共和政派</strong>の対立で、国論を二分</p>\n<p><strong class=\"source-bold\">自然主義作家<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゾラ</strong></span></strong>が軍部を批判（「<strong class=\"source-bold\">私は<ruby>弾劾<rt>だんがい</rt></ruby>する</strong>」）</p></blockquote>\n<p>※ドレフュス事件の影響</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シオニズム運動</strong></span>の本格化……ジャーナリストの<strong class=\"source-bold\">ヘルツル</strong>が中心</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">急進社会党</strong>の結成［1901］ ……ドレフュス事件での共和政擁護派が結集</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政教分離法</strong></span>［1905］……教会の政治介入と、教会への政府の援助を禁止</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">普仏戦争が終わって……フランスでは、ドイツへの復讐心が高まった！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">普仏戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロイセン＝フランス戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独仏戦争</strong></span>】</strong>後、フランスでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第三共和政</strong></span>が成立したけど、初期の議会は<strong class=\"source-bold\">王党派が中心</strong>で、議会と対立した<strong class=\"source-bold\">ティエールが失脚</strong>しちゃうくらい混乱していたんだ。ただ、国民はもう王政には戻りたくないから、選挙のたびに<strong class=\"source-bold\">共和派が議席を伸ばして</strong>、1875年に<strong class=\"source-bold\">三権分立、二院制、大統領制</strong>を定めた<strong class=\"source-bold\">第三共和政憲法</strong>が成立したよ。これ以後、共和派はラ＝マルセイエーズを国歌に定めたり、バスティーユを<ruby>襲撃<rt>しゅうげき</rt></ruby>した7月14日を祝日にしたりして、自分たちを<strong class=\"source-bold\">フランス革命の正統な<ruby>継承者<rt>けいしょうしゃ</rt></ruby></strong>であることを宣伝し、共和派が王党派に対抗して連立政権をつくる<strong class=\"source-bold\">議会共和政【オポルテュニスム】</strong>となった。ただ、王党派の勢力も残ったから、<strong class=\"source-bold\">議会では共和派と王党派の対立</strong>が続いて、政治はずっと不安定だったんだ。</p>",
  "219": "<h2>219</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">フランス ～第三共和政の諸問題～</u></p>\n<p>政治が混乱する一方で、<strong class=\"source-bold\">フランス国民に共通する意識</strong>もあった。それが<strong class=\"source-bold\">ドイツに対する復讐心</strong>だよ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>を奪われたフランス人は、ドイツを深く恨み、「<strong class=\"source-bold\">アルザス・ロレーヌを取り返すまでは、絶対ドイツは許さない</strong>」って思っていた。この時期の<strong class=\"source-bold\">海外植民地の拡大</strong>（例えば、アフリカ横断政策とかベトナム保護国化ね）は、普仏戦争で傷ついたフランス人のプライドを少しは満足させたかもしれないけど、そうこうしている間にも<strong class=\"source-bold\">ビスマルクがフランスを国際的に孤立させてくる</strong>。フランス人のドイツへの恨みは、どんどん大きくなるばかりだよ。こうした<strong class=\"source-bold\">対独復讐心</strong>を背景に起きたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>だ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ブーランジェ将軍がドイツへの復讐をあおり、民衆が熱狂！</strong></span></h4>\n<p>1880年代にフランスは<ruby>不況<rt>ふきょう</rt></ruby>となり、<strong class=\"source-bold\">労働者のストライキ</strong>がしょっちゅう起きた。民衆の味方をして人気を上げた<strong class=\"source-bold\">元陸相のブーランジェ将軍</strong>は、<strong class=\"source-bold\">ドイツに対して強硬な態度</strong>をとり、「復讐将軍」として人気をさらに高めた。すると、<strong class=\"source-bold\">政府に反対する勢力が次々とブーランジェのもとに結集</strong>して、<ruby>右翼<rt>うよく</rt></ruby>の王党派から<ruby>左翼<rt>さよく</rt></ruby>の急進派までも巻き込む<strong class=\"source-bold\">反議会主義、憲法改正</strong>を主張する反共和政運動になった。そして1889年にはパリの大衆運動が、<strong class=\"source-bold\">クーデタが起きる寸前</strong>まで盛り上がったよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>だ。ただ、ブーランジェ将軍は最後の最後で決断をためらった……。結局<strong class=\"source-bold\">クーデタは実行できず、ベルギーに<ruby>亡命<rt>ぼうめい</rt></ruby>して自殺</strong>したんだよ。</p>\n<p>この1カ月後には、<strong class=\"source-bold\">フランス革命100周年を記念するパリ<ruby>万国博覧会<rt>ばんこくはくらんかい</rt></ruby></strong>が開会し、革命を<ruby>讃<rt>たた</rt></ruby>えるイベントが次々と開かれて、国民的な友愛と連携が図られたよ。ちなみに、<strong class=\"source-bold\">エッフェル塔</strong>ができたのはこの時だ。このイベントも、ある意味ではアルザス・ロレーヌを失ったフランス人の心の傷を<ruby>癒<rt>いや</rt></ruby>したんだね。</p>\n<blockquote><p>右翼から左翼までブーランジェのもとに結集した！ そこまでドイツを恨んでたんだね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツへの復讐心と反ユダヤ主義が重なり、ドレフュス事件が起きた！</strong></span></h4>\n<p>ブーランジェ事件のあと、政権が取れなかった<strong class=\"source-bold\">王党派</strong>、特に<strong class=\"source-bold\">カトリック教会</strong>が権力を復活させようと、<strong class=\"source-bold\">共和派と対立</strong>していた。この対立からフランス国内が真っ二つに分裂したのが、<strong class=\"source-bold\">ユダヤ系軍人のスパイ<ruby>冤罪<rt>えんざい</rt></ruby>事件</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドレフュス事件</strong></span>だよ。</p>\n<p>事件の発端は、フランス軍のなかで起きたドイツのスパイ事件だ。フランスの軍事機密がドイツに漏れてることが発覚してスパイの捜査が始まり、1894年に<ruby>参謀<rt>さんぼう</rt></ruby>本部の<strong class=\"source-bold\">ユダヤ人将校</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドレフュス</strong></span><ruby>大尉<rt>たいい</rt></ruby>が告発されて、終身刑になった。フランスでは<strong class=\"source-bold\">東欧からのユダヤ系移民</strong>が増えていたから、国内で<strong class=\"source-bold\">ユダヤ人に対する反感</strong>が高まり、新聞などのジャーナリズムもさんざんドレフュスを攻撃したんだけど……<strong class=\"source-bold\">真犯人が見つかった</strong>んだよ。これじゃあ、ドレフュスは無罪にならないとおかしいよね。しかも、次々に明らかになる軍部の証拠隠滅とねつ造……。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "220": "<h2>220</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p>こうして<strong class=\"source-bold\">軍部への批判</strong>が爆発した。<strong class=\"source-bold\">自然主義作家</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゾラ</strong></span>が「<strong class=\"source-bold\">私は<ruby>弾劾<rt>だんがい</rt></ruby>する！</strong>」という大統領への公開質問状を新聞に載せると、共和派の<strong class=\"source-bold\">政治家、知識人や学生がドレフュスを<ruby>擁護<rt>ようご</rt></ruby>して再審</strong>を訴えた。一方、偽装工作がバレた軍部が、メンツを保つために再審を<strong class=\"source-bold\">拒否</strong>すると、<ruby>右翼<rt>うよく</rt></ruby>の<strong class=\"source-bold\">国家主義者</strong>や、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ユダヤ主義</strong></span>をあおる<strong class=\"source-bold\">カトリック教会が軍部を支持</strong>したので、フランス国内では<strong class=\"source-bold\">共和政擁護派</strong>（ドレフュスを無罪として軍部を批判したグループ）と<strong class=\"source-bold\">反共和政派</strong>（軍部を支持して、ドレフュスを有罪にしようとしたグループ）が激しく対立したんだ。しかも同じ時期に、<strong class=\"source-bold\">ファショダ事件でイギリスに譲歩した政府に対する批判</strong>が重なり、議会を中心とする共和政は危機に陥った。事件は、<strong class=\"source-bold\">大統領がドレフュスを釈放</strong>する命令を出して一応解決にしたけど、最終的にドレフュスが無罪を勝ち取ったのは、7年後の1906年だ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドレフュス事件がフランスの政治を変えた！</strong></span></h4>\n<p>ドレフュス事件を受けて、フランスでは<strong class=\"source-bold\">これまでバラバラだった共和派</strong>が、1901年、<strong class=\"source-bold\">右派に対抗</strong>して<strong class=\"source-bold\">急進社会党</strong>を結成し、<strong class=\"source-bold\">人権擁護</strong>や<strong class=\"source-bold\">政教分離</strong>の実現を目指した。あっ、名前にダマされないように！ 急進社会党って名前だけど<strong class=\"source-bold\">社会主義じゃなくて、ドレフュスを擁護した連中</strong>が集まった政党だよ。さらに、これまで<strong class=\"source-bold\">政党をつくっていなかった社会主義者</strong>も、1905年に<strong class=\"source-bold\">フランス社会党【統一社会党】</strong>を結成して、共和派内閣を助けた。こうしてフランスでは、政治の近代化が進められたんだ。</p>\n<p>それから一番問題だったのが、<strong class=\"source-bold\">カトリック教会の政治への<ruby>介入<rt>かいにゅう</rt></ruby></strong>だ。ずっと<strong class=\"source-bold\">保守勢力の中心</strong>は教会だったからね。そこで、1905年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政教分離法</strong></span>が制定されて、宗教に対する国の援助が一切排除され、教会の政治活動も禁止になった。これにより、ナポレオンが結んだ宗教協約<strong class=\"source-bold\">【コンコルダート】</strong>は破棄されたよ。こんなふうに、<strong class=\"source-bold\">ドレフュス事件</strong>はフランスにおける<strong class=\"source-bold\">軍の民主化</strong>や<strong class=\"source-bold\">政教分離</strong>のきっかけになったんだ。</p>\n<blockquote><p>ドレフュス事件のあと、フランスでは政教分離と軍の民主化が進んだよ</p></blockquote>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">フランスの政党</strong>……<strong class=\"source-bold\">名前にダマされちゃダメ！</strong></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">急進社会党</strong>［1901結成］ ……<u data-source-underline-color=\"gray\" style=\"text-decoration-color:#777777\"><strong class=\"source-bold\">社会主義政党ではない</strong></u></p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドレフュス事件</strong></span>での共和政擁護派を結集</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">フランス社会党【統一社会党】</strong>［1905結成］ ……<u data-source-underline-color=\"gray\" style=\"text-decoration-color:#777777\"><strong class=\"source-bold\">社会主義政党</strong></u></p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">第2インターナショナル</strong>のアムステルダム決議を受け、社会主義者が結集</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">サンディカリズム（労働組合主義）</strong>が強く、労働総同盟は不参加</p></blockquote>",
  "221": "<h2>221</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">フランス ～第三共和政の諸問題～</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">反ユダヤ主義の高まりに対して、ユダヤ人のシオニズム運動が始まった！</strong></span></h4>\n<p>ドレフュス事件での<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ユダヤ主義</strong></span>の高まりを見て、ユダヤ人は大きなショックを受けたよ。だって、明らかな<ruby>冤罪<rt>えんざい</rt></ruby>事件なのに、どこの国も助けてくれないんだもん。「<strong class=\"source-bold\">ユダヤ人国家をつくらないと、いつまでたっても差別される！</strong>」って思ったユダヤ人たちは、<strong class=\"source-bold\">パレスチナにユダヤ人国家を建設</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シオニズム運動</strong></span>を本格化させたんだ。ジャーナリストの<strong class=\"source-bold\">ヘルツル</strong>を中心に、スイスのバーゼルで<strong class=\"source-bold\">第1回シオニスト会議</strong>が開かれて世界シオニスト機構を設立すると、以後、パレスチナへのユダヤ人の移住が進められることになったよ。</p>\n<blockquote><p>この時期の移住者はそんなに多くないよ。ユダヤ人の移住が急増するのは、ドイツでヒトラー政権ができたあとだ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">フランスの帝国主義と社会主義運動</strong></span></h4>\n<p>フランスは<strong class=\"source-bold\">ビスマルク外交によってヨーロッパでは孤立していた</strong>けど、<strong class=\"source-bold\">アジアやアフリカでは植民地を拡大</strong>して、イギリスに次ぐ植民地帝国を形成していたよね。そして、1890年には国際情勢が大きく変化するよ。ドイツで<strong class=\"source-bold\">ビスマルクが退陣</strong>して<strong class=\"source-bold\">ヴィルヘルム2世の親政</strong>になると、<strong class=\"source-bold\">ロシアとドイツの関係が急速に悪化</strong>した。原因などは次回にじっくり話すとして、ロシアがドイツと対立したことで、同じように<strong class=\"source-bold\">ドイツと対立していたフランスはロシアと接近</strong>したんだよ。ほら、「キライなヤツが一致すると愛が芽生える」。どっちもドイツがキライだから、<strong class=\"source-bold\">反ドイツで同盟できる</strong>ってわけ。こうして1891年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露仏<rt>ろふつ</rt></ruby>同盟</strong></span>に合意すると、<strong class=\"source-bold\">フランスからロシアへの投資</strong>が急激に増えたよ。例えば、フランスからの投資でロシアは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア鉄道</strong></span>を建設したんだよ。</p>\n<p>実は<strong class=\"source-bold\">フランスの銀行はむちゃくちゃお金を持ってる</strong>んだよ。フランスは革命で土地を得た中小農民が、いざという時のために貯金してるからね。ただ、<strong class=\"source-bold\">国内の工業発展は停滞気味</strong>……国内に投資先があまりなかったから、<strong class=\"source-bold\">海外に投資先を求めた</strong>んだね。こうして<strong class=\"source-bold\">ロシア</strong>だけじゃなく、<strong class=\"source-bold\">トルコ</strong>や<strong class=\"source-bold\">バルカン諸国</strong>にも盛んに投資したから、<strong class=\"source-bold\"><ruby>高利貸<rt>こうりがし</rt></ruby>帝国主義</strong>と呼ばれているよ。</p>\n<p>一方、<strong class=\"source-bold\">労働者</strong>にはまだ革命の想い出が生きている。フランスの労働者って、政党をつくって議会に進出するより、<strong class=\"source-bold\">労働組合</strong>をつくって<strong class=\"source-bold\">ストライキなどの直接行動</strong>に訴えたり、<strong class=\"source-bold\">デモ</strong>をやったほうが手っ取り早いと思っているんだもん。だから、<strong class=\"source-bold\">労働総同盟【CGT】</strong>を中心に、<strong class=\"source-bold\">議会主義を否定</strong>して<strong class=\"source-bold\">直接行動による社会改革</strong>を目指した。これを<strong class=\"source-bold\">サンディカリズム（労働組合主義）</strong>というんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "222": "<h2>222</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <strong class=\"source-bold\">ドイツ ～ドイツの発展と社会主義～</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">新皇帝ヴィルヘルム2世の登場で、ドイツの政策は180度転換！</strong></span></h4>\n<p>ドイツ帝国の成立後、皇帝<strong class=\"source-bold\">ヴィルヘルム1世</strong>のもとで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>が<ruby>宰相<rt>さいしょう</rt></ruby>として政治を動かしていたよね。しかし、ビスマルクが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義者<ruby>鎮圧<rt>ちんあつ</rt></ruby>法</strong></span>で<ruby>弾圧<rt>だんあつ</rt></ruby>していた<strong class=\"source-bold\">社会主義運動がだんだん激しくなっていた</strong>んだ。さらに、皇帝ヴィルヘルム1世が91歳で亡くなり、29歳の若い<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>が即位すると、ドイツ国内には「古い体制を<ruby>刷新<rt>さっしん</rt></ruby>して、<strong class=\"source-bold\">新しいドイツ</strong>を！」というムードが広がったんだよ。</p>\n<p>1890年ごろの<strong class=\"source-bold\">ドイツでは工業が発展</strong>し、<strong class=\"source-bold\">重化学工業</strong>を中心に<strong class=\"source-bold\">クルップ</strong>やジーメンスなどの大企業（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンツェルン</strong></span>）が現れて、「<strong class=\"source-bold\">いよいよイギリスに追いつくんじゃないか！</strong>」って雰囲気があったんだ。その一方で、産業の中心が<strong class=\"source-bold\">農業から工業に転換</strong>されて労働者も増えていたから、<strong class=\"source-bold\">労働運動も活発になり</strong>、たびたびストライキも起きた。ビスマルクは徹底的な鎮圧を主張したけど、即位したばかりの新皇帝<strong class=\"source-bold\">ヴィルヘルム2世は人気を取りたい</strong>って気持ちもあって、労働者に理解を示した。ヴィルヘルム2世は「ビスマルクのジジイよりも、オレのほうがいいだろ！」って言いたいんだよ。だから、<strong class=\"source-bold\">ビスマルクの政策は全部ひっくり返したい</strong>。</p>\n<p>こうして<strong class=\"source-bold\">皇帝と対立したビスマルクが退陣</strong>すると、じきに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世の親政</strong></span>が始まった。親政っていうのは、<strong class=\"source-bold\">皇帝が自分の意思で政治をやる</strong>ってことね。ヴィルヘルム2世はすぐに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義者鎮圧法を廃止</strong></span>して、労働者階級を体制側の味方にしようとした。背景はドイツにおける<strong class=\"source-bold\">社会主義の拡大</strong>だよ。</p>\n<blockquote><p>ヴィルヘルム2世の政策は、「内政も外交も、ビスマルクの逆」って覚えておこう！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">世界最大の社会主義政党、ドイツ社会民主党ができた！</strong></span></h4>\n<p>ビスマルク時代に弾圧されていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会主義労働者党</strong></span>は隠れて活動を続けていたんだけど、1890年に<strong class=\"source-bold\">社会主義者鎮圧法が廃止</strong>されると復活し、党の名前も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会民主党</strong></span>と変えて、正式に<strong class=\"source-bold\">マルクス主義を採用</strong>したよ（<strong class=\"source-bold\">エルフルト<ruby>綱領<rt>こうりょう</rt></ruby></strong>）。これ以後、労働組合と手を組んで、国会の選挙では議席を増やしたんだ。</p>\n<p>こうなると、<strong class=\"source-bold\">革命を目標とするマルクス主義が実態にあわなくなる</strong>よね。自分たちが進出している議会を革命で<ruby>潰<rt>つぶ</rt></ruby>すのは、単なる自爆だ。こうして19世紀末には、<strong class=\"source-bold\">ベルンシュタイン</strong>を理論的な指導者とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">修正主義</strong></span>が現れた。これは、<strong class=\"source-bold\">議会で勢力を拡大</strong>して、<strong class=\"source-bold\">議会を通じた社会政策</strong>によって社会主義を実現するって考え方だ。<strong class=\"source-bold\">イギリスの労働党と似てる</strong>よね。そして、順調に議席を増やした社会民主党は、<strong class=\"source-bold\">1912年の総選挙で議会内第1党になった</strong>よ。</p>",
  "223": "<h2>223</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツ ～ドイツの発展と社会主義～</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">社会主義者が国際的に連携した組織も確認しておこう！</strong></span></h4>\n<p>ここで、<strong class=\"source-bold\">社会主義者が国際的に連携してつくった組織</strong>も確認しておこう。まず、1863年の<strong class=\"source-bold\">ポーランド反乱</strong>を各国の労働者たちが支援したことをきっかけに、1864年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span>を中心に<strong class=\"source-bold\">ロンドン</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1インターナショナル</strong></span>（<strong class=\"source-bold\">国際労働者協会を、のちにこう呼んだ</strong>）が結成されたよ。ただ、<strong class=\"source-bold\">パリ＝コミューンへの対応</strong>から、内部対立が表に出てきちゃった。マルクスは「<strong class=\"source-bold\">労働者が革命政党や政府をつくるべき</strong>」って思っていたから、コミューンを支持したんだけど、<strong class=\"source-bold\">無政府主義者</strong>の<strong class=\"source-bold\">バクーニン</strong>は「革命政党や革命政府だって、しょせんは国家権力だ」って主張したから、<strong class=\"source-bold\">マルクスと対立して除名</strong>されちゃった……。しかも、<strong class=\"source-bold\">パリ＝コミューンを支持したために各国の政府に弾圧され</strong>、活動停止になっちゃったんだ。</p>\n<p>そして1889年、<strong class=\"source-bold\">フランス革命100周年</strong>を記念して、各国の<strong class=\"source-bold\">社会主義政党や労働者組織</strong>で結成されたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2インターナショナル</strong></span>だ。中心となったのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会民主党</strong></span>だよ。気をつけてほしいのは、<strong class=\"source-bold\">第1インターナショナルは社会主義者が個人で参加</strong>するのに対して、<strong class=\"source-bold\">第2インターナショナルは政党や組織単位で参加</strong>するってところね。また、アジアからは日本の社会主義者である<ruby>片山潜<rt>かたやません</rt></ruby>なども参加したよ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">社会主義者の国際的連携</strong></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1インターナショナル</strong></span>［1864〜76］</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span>を中心に<strong class=\"source-bold\">ロンドン</strong>で結成</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">パリ＝コミューンへの対応</strong>から、<strong class=\"source-bold\">マルクス</strong>と<strong class=\"source-bold\">無政府主義者</strong>が対立</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2インターナショナル</strong></span>［1889〜1914］</p>\n<blockquote><p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">フランス革命100周年</strong>を記念して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ</strong></span>で結成</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会民主党</strong></span>が主導し、おもに<strong class=\"source-bold\">欧米諸国の社会主義政党</strong>が加盟</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツの将来は海上にあり！ ヴィルヘルム2世が「世界政策」を推進！</strong></span></h4>\n<p><strong class=\"source-bold\">工業国への転換を果たしたドイツ</strong>では、<strong class=\"source-bold\">工業製品の輸出</strong>が増えるのにあわせて<strong class=\"source-bold\">海運業も発展</strong>したよ。国内の大企業はもっと輸出を拡大したいから、他の<ruby>列強<rt>れっきょう</rt></ruby>に負けないように「<strong class=\"source-bold\">ドイツも対外進出してほしい！</strong>」って思っていた。そして<strong class=\"source-bold\">ヴィルヘルム2世</strong>も、<strong class=\"source-bold\">ビスマルク時代の古い外交には縛られたくない</strong>。もっと植民地がほしいし、海への出口を増やすためにバルカン半島に進出したい。こうなると、<strong class=\"source-bold\">ロシアとの対立は避けられない</strong>から、1890年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>はロシアとの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約の更新を拒否</strong></span>したんだ。ここから「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界政策</strong></span>」が始まるよ！</p>\n<p>ヴィルヘルム2世は「<strong class=\"source-bold\">ドイツの将来は海上にあり！</strong>」って宣言して、積極的な対外進出のために<strong class=\"source-bold\">海軍を拡張</strong>した。さらに、1899年には<strong class=\"source-bold\">トルコ</strong>から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード鉄道の<ruby>敷設<rt>ふせつ</rt></ruby>権</strong></span>を獲得し、<strong class=\"source-bold\">西アジアへの進出</strong>を狙ったよ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3B政策</strong></span>」だ。<strong class=\"source-bold\">ドイツの</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "224": "<h2>224</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p><strong class=\"source-bold\">首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン</strong></span>、トルコの首都イスタンブル</strong>（旧名が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビザンティウム</strong></span>）、そして<strong class=\"source-bold\">イラク</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バグダード</strong></span>を鉄道で結んで、最終的には<strong class=\"source-bold\">ペルシア湾まで進出する</strong>のが目標だ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">3B政策（独）</strong></span></td><td>ベルリン<br>ビザンティウム<br>バグダード</td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3C政策（英）</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span> カイロ<br><span data-source-color=\"red\" style=\"color:#e52715\">●</span> カルカッタ<br><span data-source-color=\"red\" style=\"color:#e52715\">●</span> ケープタウン</td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>が<strong class=\"source-bold\">カイロ・カルカッタ・ケープタウン</strong>の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3C政策</strong></span>」、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ</strong></span>が<strong class=\"source-bold\">ベルリン・ビザンティウム・バグダード</strong>の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3B政策</strong></span>」だ</p></blockquote>\n<p>この動きを警戒したのが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3C政策</strong></span>」をとる<strong class=\"source-bold\">イギリス</strong>だよ。だって、ドイツがペルシア湾まで進出してきたら、たぶんインド洋にも出てくる……。<strong class=\"source-bold\">ドイツの動きを警戒したイギリス</strong>は、「ドイツはボンベイ（Bombay）やベンガル（Bengal）までくるつもりじゃないか？ こりゃ、3Bどころか4Bや5Bだろ」って焦った。あっ！ 4Bやら5Bは正式な言い方じゃなくて、僕が勝手に言ってるだけだから、入試で書いちゃダメよ。イメージね、あくまでもイメージ。</p>\n<p>こうなると、<strong class=\"source-bold\">イギリスもドイツに対抗して海軍をさらに強くしなきゃマズい</strong>。だから、ドイツとイギリスは相手よりも強い海軍をつくろうとして<strong class=\"source-bold\"><ruby>建艦<rt>けんかん</rt></ruby>競争</strong>を繰り広げた。だんだん危ない状況になってきたね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <strong class=\"source-bold\">ロシア ～ロシアの社会主義と第1次ロシア革命～</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><ruby>露仏<rt>ろふつ</rt></ruby>同盟が成立して、ロシアでも資本主義の発展が始まる！</strong></span></h4>\n<p><strong class=\"source-bold\">アレクサンドル2世</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>農奴<rt>のうど</rt></ruby>解放令</strong></span>を出したあとも、<strong class=\"source-bold\">ロシアはなかなか産業が発展しなかった</strong>。なぜって……産業の担い手であるはずの<strong class=\"source-bold\">市民階級が成長しなかった</strong>からだ。要するにお金がないからだよ。工場の建設、鉄道の敷設、鉱山の開発……何をするにもお金がかかるからね。<strong class=\"source-bold\">外国からの投資</strong>といっても、どこの国だって自分の国の発展が最優先でしょ？ しかも、一番お金を持っている<strong class=\"source-bold\">イギリスとは、南下政策をめぐって対立</strong>している……。この状態は、アレクサンドル2世が暗殺されて<strong class=\"source-bold\">アレクサンドル3世</strong>が即位してからも、あまり変わらなかったんだよ。</p>\n<p>そんなロシアにも、やっとチャンスがめぐってきた！ <strong class=\"source-bold\">ドイツでビスマルクが退</strong></p>",
  "225": "<h2>225</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア ～ロシアの社会主義と第1次ロシア革命～</u></p>\n<p><strong class=\"source-bold\">陣</strong>すると、<strong class=\"source-bold\">ヴィルヘルム2世</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約の更新を拒否</strong></span>してきた。はっきり言って、「ロシアは見捨てられた……」。そしたら、<strong class=\"source-bold\">ドイツに孤立させられていたフランス</strong>が、「ドイツがキライな者同士、仲良くやろう」って接近してきて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露仏同盟</strong></span>が成立したんだ。これにより、<strong class=\"source-bold\">フランスからの投資が増えたロシア</strong>では、蔵相<strong class=\"source-bold\">ウィッテ</strong>が中心になって工場が建設されたり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア鉄道</strong></span>が建設されたりと、一気に工業化が進んだよ。この<strong class=\"source-bold\">工業化を支えた労働力</strong>は、農奴解放後に<strong class=\"source-bold\">都市に流れ込んでいた没落農民</strong>だ。彼らが低賃金の労働力になり、ロシア経済は急激に発展したよ。だから、農奴解放令が「<strong class=\"source-bold\">ロシア資本主義の出発点</strong>」っていわれるんだ。</p>\n<blockquote><p>ドイツがキライなフランスとロシア……「愛が芽生えてしまった」</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">労働者の増加で、ロシアでも社会主義が出現！</strong></span></h4>\n<p>20世紀初め、<strong class=\"source-bold\">ロシアの急成長がストップして<ruby>不況<rt>ふきょう</rt></ruby>となり</strong>、国内の不満が高まった。<strong class=\"source-bold\">農民運動や労働者のストライキ</strong>が全国に拡大し、いまだに残っているロシア社会の矛盾が明らかになったんだ。こうした社会運動を見た知識人や学生たちは「やっぱり<ruby>専制<rt>せんせい</rt></ruby>政治が悪い」って政府への批判を強め、<strong class=\"source-bold\">社会改革のための政党の結成</strong>を進めたんだ。</p>\n<p>1903年、<strong class=\"source-bold\">ロンドン</strong>とブリュッセルで、<ruby>亡命<rt>ぼうめい</rt></ruby>していた<strong class=\"source-bold\">社会主義者たちの大会</strong>が開かれ、実質的に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア社会民主労働党</strong></span>が結成され、<strong class=\"source-bold\">マルクス主義が採用された</strong>んだけど、革命のやり方をめぐって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>が主導する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ</strong></span>（「多数派」って意味ね）と<strong class=\"source-bold\">マルトフ</strong>が主導する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">メンシェヴィキ</strong></span>（こっちは「少数派」って意味だ）に党が分裂してしまったんだ。ここは、次ページの図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.226</strong></span>を見ながら説明しよう。ちなみに「多数派」「少数派」は党人事の問題で、実際の党員数ではないよ。</p>\n<p><strong class=\"source-bold\">マルトフ</strong>が指導する<strong class=\"source-bold\">メンシェヴィキ</strong>は、<strong class=\"source-bold\">ロシアの現状は絶対王政</strong>だから、まずは幅広く<strong class=\"source-bold\">資本家などとも協力</strong>してブルジョワ革命を起こし、資本主義を発展させてから社会主義の段階へと進むことを目指した。つまり、<strong class=\"source-bold\">次の革命はブルジョワ革命</strong>だ。これは、<strong class=\"source-bold\">マルクス主義の原則をそのまま目標にした</strong>ものと考えられるね。あとから合流した<strong class=\"source-bold\">プレハーノフ</strong>が、メンシェヴィキの中心になるよ。</p>\n<p>これに対し<strong class=\"source-bold\">レーニン</strong>を中心とする<strong class=\"source-bold\">ボリシェヴィキ</strong>は、<strong class=\"source-bold\">ロシアは絶対王政のもとですでに資本主義に突入</strong>して労働者階級も出現しているから、「<strong class=\"source-bold\">絶対王政を倒すブルジョワ革命と資本主義を倒す社会主義革命</strong>を一気にやっちゃえ〜」って考えた（<strong class=\"source-bold\">二段階連続革命</strong>）。つまり、<strong class=\"source-bold\">次の革命は社会主義革命【プロレタリア革命】</strong>なんだ。ていうかこれ、マルクス主義をかなりねじ曲げてるから、実現には無理がある。だから、<strong class=\"source-bold\">少数の革命集団</strong>による<strong class=\"source-bold\">武力革命</strong>をやろうとしたんだね。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "226": "<h2>226</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p>ほかに、<ruby>亡命<rt>ぼうめい</rt></ruby>先で結成された社会民主労働党だけじゃなくて、国内でも政党の結成が進んだよ。<strong class=\"source-bold\">ナロードニキ</strong>のうちテロリズムに走らなかった連中は、<strong class=\"source-bold\">農村共同体（ミール）を基盤</strong>にしたロシア型の社会主義を目指して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span>／社会主義者・革命家党】</strong>を結成した。これらの政党はロシア革命のところでまた出てくるからね。</p>\n<h4><strong class=\"source-bold\">〈マルクス主義とボリシェヴィキ・メンシェヴィキ〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td><strong class=\"source-bold\">ブルジョワ革命</strong></td><td></td><td><strong class=\"source-bold\">社会主義革命</strong></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">絶対王政</strong></span></td><td><span data-source-marker=\"outline-arrow\" style=\"color:#001000\">⇨</span></td><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">資本主義</strong></span></td><td><span data-source-marker=\"outline-arrow\" style=\"color:#001000\">⇨</span></td><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">社会主義</strong></span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">メンシェヴィキ</strong></td><td><span data-source-marker=\"point\" style=\"color:#001000\">◯</span><br>ロシアの現状</td><td><span data-source-color=\"brown\" data-source-marker=\"arrow\" style=\"color:#a43725\">→</span></td><td><span data-source-color=\"brown\" data-source-marker=\"point\" style=\"color:#a43725\">◯</span><br><span data-source-color=\"brown\" style=\"color:#a43725\">当面の目標<br>➡次の革命はブルジョワ革命</span></td><td><span data-source-color=\"green\" data-source-marker=\"arrow\" style=\"color:#859476\">→</span></td><td><span data-source-color=\"green\" data-source-marker=\"dashed-point\" style=\"color:#859476\">◌</span><br>最終目標</td></tr><tr><td><strong class=\"source-bold\">ボリシェヴィキ</strong></td><td><span data-source-marker=\"oval\" style=\"color:#001000\">⬭</span><br>ロシアの現状<br>➡絶対王政のもとで資本主義に突入</td><td></td><td></td><td><span data-source-color=\"red\" data-source-marker=\"arrow\" style=\"color:#e52715\">→</span></td><td><span data-source-color=\"red\" data-source-marker=\"point\" style=\"color:#e52715\">◯</span><br><span data-source-color=\"red\" style=\"color:#e52715\">目標<br>➡次の革命は社会主義革命</span></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">食糧難になったペテルブルクで、第1次ロシア革命が起こった！</strong></span></h4>\n<p>20世紀に入って、<strong class=\"source-bold\">ロシア国内の状況はますますひどくなった</strong>。工業発展を優先してきたロシアは、農民から穀物を取り上げ、それを輸出して資金を確保した。要は「<strong class=\"source-bold\">工業発展のためなら、農民が<ruby>飢<rt>う</rt></ruby>え<ruby>死<rt>じ</rt></ruby>にしてもいい</strong>」っていう政策だ。これに対して農民は、集団で地主を襲うなどの反乱を起こし、さらに社会不安から<strong class=\"source-bold\">ユダヤ人への集団襲撃（ポグロム）</strong>なども激しくなったんだ。</p>\n<p>こうした状況のまま<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争</strong></span>に突入したロシアは、<strong class=\"source-bold\">開戦によって国民生活がさらに苦しくなった</strong>。同盟国フランスからの援助も思うように得られず、首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペテルブルク</strong></span>などの<strong class=\"source-bold\">都市では食糧難が起きていた</strong>んだ。しかし、当時の皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span>は<strong class=\"source-bold\">国民生活にはまるで興味なし</strong>……ニコライ2世は、病気の息子（皇太子）のアレクセイの体調ばかり気にしていたんだよね。「こりゃダメだ」。</p>\n<p>1905年1月、<strong class=\"source-bold\">司祭ガポン</strong>に率いられた首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペテルブルク</strong></span>の労働者やその家族たち約10万人は、<strong class=\"source-bold\">戦争の停止、労働時間の短縮、政治的自由、法のもとの平等</strong>などを求めて（彼らはこれを「プラウダ」と呼んだよ。ロシア語で「正義」って意味だ）、<strong class=\"source-bold\">皇帝のいる<ruby>冬宮<rt>とうきゅう</rt></ruby>を目指すデモ</strong>を始めた。彼らは、「プラウダ」が受け入れられなけ</p>",
  "227": "<h2>227</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア ～ロシアの社会主義と第1次ロシア革命～</u></p>\n<p>れば宮殿の前で死ぬつもりだと言って、軍隊が脅かしてもデモを続けたから、ついに<strong class=\"source-bold\">軍隊が発砲</strong>！ 多数の死者を出した。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>血<rt>ち</rt></ruby>の日曜日事件</strong></span>だ。民衆は「皇帝さまに撃たれた〜」って大騒ぎだ！</p>\n<p>「血の日曜日事件」をきっかけに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次ロシア革命</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1905年革命</strong></span>】</strong>が始まった。人びとの間に残っていたツァーリ<ruby>崇拝<rt>すうはい</rt></ruby>がなくなって、<strong class=\"source-bold\">全国各地でストライキや暴動が起こった</strong>。各地で労働者と軍隊が衝突すると、各都市の<strong class=\"source-bold\">労働者たちは自分たちの自治組織<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト</strong></span>（評議会）をつくって</strong>、憲法制定や議会の開設を要求した。さらに<strong class=\"source-bold\">軍の内部にも革命が広がって</strong>、日本海海戦で敗れたニュースが伝わると<ruby>専制<rt>せんせい</rt></ruby>政治への<strong class=\"source-bold\">批判が爆発</strong>、黒海艦隊の戦艦<strong class=\"source-bold\">ポチョムキン号</strong>では<strong class=\"source-bold\">水兵の反乱</strong>が起きたんだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">第1次ロシア革命【1905年革命】</strong></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日露戦争</strong></span><ruby>勃発<rt>ぼっぱつ</rt></ruby>［1904］ ……<strong class=\"source-bold\">都市における食糧難</strong>の発生</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次ロシア革命</strong></span>［1905.1〜05.9］ ……当時の皇帝は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span></p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">血の日曜日事件</strong></span>［1905.1］ ……指導者：<strong class=\"source-bold\">ガポン</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> 日露戦争中に、首都：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペテルブルク</strong></span>の<strong class=\"source-bold\">冬宮</strong>で発生 <span data-source-color=\"green\" style=\"color:#315837\">➡</span> 全国各地へ暴動が波及</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト</strong></span> <strong class=\"source-bold\">【評議会】</strong>の結成……都市で発生した<strong class=\"source-bold\">労働者の自治組織</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> 軍内部にも革命が波及……<strong class=\"source-bold\">戦艦ポチョムキン号の反乱</strong>［1905.6］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月宣言</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月<ruby>勅令<rt>ちょくれい</rt></ruby></strong></span>】</strong>［1905］ ……起草者は<strong class=\"source-bold\">ウィッテ</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドゥーマ</strong></span>（帝政ロシア国会の下院）の開設［1906］……<strong class=\"source-bold\">制限選挙</strong>で選出。</p>\n<p>第1党はブルジョワ中心の<strong class=\"source-bold\">立憲民主党【カデット】</strong></p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> 第1次革命後のロシア</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span> 首相：<strong class=\"source-bold\">ウィッテ</strong>による<strong class=\"source-bold\">自由主義改革</strong>［任1905〜06］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span> <strong class=\"source-bold\">保守派の反発</strong>。ニコライ2世はウィッテを解任</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> 首相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ストルイピン</strong></span>による<strong class=\"source-bold\">反動政治</strong>［任1906〜11］……自由主義を<ruby>弾圧<rt>だんあつ</rt></ruby></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミールの解体</strong></span>……<strong class=\"source-bold\">自作農の創出</strong>が口実。<strong class=\"source-bold\">農民の反抗と革命の温床</strong>とみなした</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">革命を<ruby>鎮<rt>しず</rt></ruby>めるために、ニコライ2世が憲法制定と国会開設を約束！</strong></span></h4>\n<p><strong class=\"source-bold\">都市労働者、農民、兵士</strong>など<strong class=\"source-bold\">全国に革命が拡大</strong>したから、ロシアは日露戦争を終わらせるしかなくなったんだ。さらに、<strong class=\"source-bold\">自由主義者の要求する政治改革</strong>をやらないと革命が終わりそうになかったから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span>は仕方なく<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月宣言</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月勅令</strong></span>】</strong>を発布して、<strong class=\"source-bold\">国会開設と憲法の制定を約束</strong>したんだ。そして、十月宣言を起草した<strong class=\"source-bold\">ウィッテ</strong>を首相として、<strong class=\"source-bold\">自由主義改革</strong>を進めたよ。</p>\n<p>1906年、十月宣言での約束通り<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドゥーマ</strong></span>（帝政ロシア国会の下院）が開設された</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "228": "<h2>228</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p>んだけど、<strong class=\"source-bold\">制限選挙</strong>だったから<strong class=\"source-bold\">ブルジョワ政党</strong>の<strong class=\"source-bold\">立憲民主党【カデット】</strong>が第1党になった。ただ、この議会には制約が多かったんだよ。制定された憲法には「<strong class=\"source-bold\">皇帝に最高<ruby>専制<rt>せんせい</rt></ruby>権力がある</strong>」って書かれていたり、「<strong class=\"source-bold\">どんな法律も、皇帝の承認がないと発効しない</strong>」なんていう条項もあったから、<strong class=\"source-bold\">専制政治は何も変わらなかった</strong>。ただ、選挙で選ばれる議会ができただけでも、ロシアにとっては大きな変化だよね。</p>\n<p>しかし<strong class=\"source-bold\">こんな憲法や議会なのに、保守派の逆襲が始まった</strong>。ニコライ2世も、国内の革命を<ruby>鎮<rt>しず</rt></ruby>める「だけ」のために憲法や議会をつくったからね。革命運動さえ収まれば、もはやどっちもいらない。まず、憲法が決められる直前に、<strong class=\"source-bold\">保守派の圧力で首相ウィッテが解任</strong>され、土地改革の問題に触れた<strong class=\"source-bold\">議会もすぐに解散</strong>させられた。かわって首相になった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ストルイピン</strong></span>は<strong class=\"source-bold\">革命運動を厳しく<ruby>弾圧<rt>だんあつ</rt></ruby>する反動政治</strong>を強行する一方で、表向きは「農民がきちんと自分の土地を持てるように」と言って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">農村共同体（ミール）を解体</strong></span>した。これウラの意味だと、農民の反抗や革命の基盤になっているミールをなくしちゃえ！ってことなんだよね。ミールの解体で<strong class=\"source-bold\">貧乏な農民はさらに貧乏になった</strong>一方で、農村での助け合いから解放されて、少しは余裕があって「助けていたほう」の農民は豊かになった。こうして出現した<strong class=\"source-bold\"><ruby>富農<rt>ふのう</rt></ruby>をクラーク</strong>というんだ。その後、再び議会が開かれたものの、<strong class=\"source-bold\">ストルイピンはたびたび議会を無視</strong>したため反発を招き、1911年に<strong class=\"source-bold\">暗殺されてしまった</strong>んだ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <strong class=\"source-bold\">アメリカ合衆国 ～アメリカの帝国主義～</strong></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">工業発展によって労働者が増加！……革新主義ってなんだ？</strong></span></h4>\n<p>南北戦争後の<strong class=\"source-bold\">アメリカ</strong>では、工業発展によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独占資本</strong></span>が出現するとともに、<strong class=\"source-bold\">労働者が急増</strong>して労働運動も起こり始めた。この時代、すでに<strong class=\"source-bold\">ヨーロッパでは社会主義が拡大</strong>して各国で<strong class=\"source-bold\">社会主義政党がつくられ</strong>、アメリカでも同じような運動が起きていた。1886年には<strong class=\"source-bold\">サミュエル＝ゴンパーズ</strong>を会長に、<strong class=\"source-bold\">熟練労働者</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ労働総同盟</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">AFL</strong></span>】</strong>を結成して穏健な運動をおこない、さらに1905年には、<strong class=\"source-bold\">不熟練労働者</strong>による過激な労働組合として、<strong class=\"source-bold\">世界産業労働者同盟【IWW】</strong>もつくられた。こうした動きを警戒したのが<strong class=\"source-bold\">中産階級</strong>（まあまあ金持ちな人たち）だ。ほかに、長期の農村不況に不満を持っていた<strong class=\"source-bold\">西部や南部の農民</strong>を中心に、<strong class=\"source-bold\">ポピュリスト党【人民党】</strong>が結成されたよ。</p>\n<p>中産階級も独占資本が経済を支配するのはイヤだったけど、<strong class=\"source-bold\">独占資本が強すぎると労働者が反発</strong>して「革命だぁ〜」とか言い出すかもしれない……。<strong class=\"source-bold\">中産階級は</strong>そこそこ財産を持ってるから<strong class=\"source-bold\">社会主義にはしたくない</strong>。だから、社会主義の拡大などの<strong class=\"source-bold\">急激な変化を避ける</strong></p>\n<blockquote><p>「革新主義」って、労働者が好きなんじゃなくて、社会主義がイヤすぎて起きた動きだ</p></blockquote>",
  "229": "<h2>229</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国 ～アメリカの帝国主義～</u></p>\n<p><strong class=\"source-bold\">ため</strong>に、<strong class=\"source-bold\">独占資本を規制</strong>してまともな自由競争を求める動きが起きたんだ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">革新主義</strong></span>」だ。</p>\n<p>アメリカでは、1890年ころから<strong class=\"source-bold\">独占資本を規制</strong>する<strong class=\"source-bold\">反トラスト法</strong>が、数回にわたって制定されていたよ。まず、1890年にハリソン大統領が<strong class=\"source-bold\">シャーマン反トラスト法</strong>を制定し、その後「<strong class=\"source-bold\">革新主義</strong>」を前面に掲げる<strong class=\"source-bold\">共和党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セオドア＝ローズヴェルト</strong></span>大統領が独占資本の規制に乗り出した。ただ、<strong class=\"source-bold\">アメリカは州ごとに法律が違う</strong>から、なかなか規制は難しかったんだよ。そして、「<strong class=\"source-bold\">新しい自由【ニューフリーダム】</strong>」を掲げる<strong class=\"source-bold\">民主党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>大統領は、<strong class=\"source-bold\">クレイトン法</strong>を制定して<strong class=\"source-bold\">独占資本の不正を防ぐ</strong>ために<strong class=\"source-bold\">連邦取引委員会</strong>を成立させて、ある程度は効果を上げた。ただ、憲法に書かれた経済活動の自由とバッティングして完全に規制するのは難しかったんだけど、<strong class=\"source-bold\">労働者や農民などを保護</strong>する法律をつくって支持を拡大しようとしたんだね。</p>\n<p>じゃあ、続いてアメリカの外交について見ていこう。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">フロンティアが消滅すると……いよいよ対外進出が始まった！</strong></span></h4>\n<p>アメリカは、<strong class=\"source-bold\">1890年ごろまでほとんど対外進出をしていない</strong>よね。なぜかというと「<strong class=\"source-bold\">西部開拓</strong>」をしていたからだ。よく考えてみてね。アメリカって、建国した時は大西洋側の東部13州しかなかったのに、どんどん<strong class=\"source-bold\">西部に領土を拡大</strong>して、しかも世界中から<strong class=\"source-bold\">移民が流入</strong>して人口も増えていったでしょ。領土拡大と人口増加……要するに<strong class=\"source-bold\">国内<ruby>市場<rt>しじょう</rt></ruby>が拡大</strong>してるんだ。これって、経済的には植民地を拡大してるのと同じ効果！ だから、植民地を拡大しなくてよかったんだね。</p>\n<p>それが、<strong class=\"source-bold\">19世紀末</strong>に近づくと状況が変わったよ。1886年に<strong class=\"source-bold\">アパッチ族</strong>の<strong class=\"source-bold\">ジェロニモ</strong>の反抗を<ruby>鎮圧<rt>ちんあつ</rt></ruby>し、1890年にインディアン居留地<strong class=\"source-bold\">ウーンデッドニー</strong>で<strong class=\"source-bold\">スー族インディアンを虐殺</strong>したアメリカ政府は、1890年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フロンティア消滅</strong></span>を宣言した。フロンティアが消滅しちゃうと、<strong class=\"source-bold\">これ以後、国内<ruby>市場<rt>しじょう</rt></ruby>が急激に拡大することはない</strong>。しかも同じころ、<strong class=\"source-bold\">アメリカはイギリスを抜いて世界1位の工業国</strong>になった。だから、アメリカの1890年はむちゃくちゃ大事だよ！ 「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フロンティア消滅</strong></span>」と「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">工業生産世界1位</strong></span>」、この2つによって市場拡大への欲求が高まり、アメリカは<strong class=\"source-bold\">ラテンアメリカを標的にした対外進出を始めた</strong>んだ。</p>\n<p>1889年、ハリソン大統領がワシントンで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回パン＝アメリカ会議</strong></span>を開催し、「<strong class=\"source-bold\">パン＝アメリカ主義</strong>」を採用した。「パン＝○○」ってのは「○○の連携」って意味なんだけど、この会議では<strong class=\"source-bold\">アメリカ合衆国を中心に南北アメリカが連携</strong>する「パン＝アメリカ主義」を口実に、「<strong class=\"source-bold\">アメリカがラテンアメリカを政治的・経済的に支配してもいい</strong>」ってことにしたんだよ。</p>\n<blockquote><p>アメリカの「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1890年</strong></span>」は、絶対覚えてね。「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フロンティア消滅</strong></span>」と「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">工業生産世界1位</strong></span>」だ！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "230": "<h2>230</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">アメリカの帝国主義</strong>（<strong class=\"source-bold\">セオドア＝ローズヴェルトまで</strong>）</h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回パン＝アメリカ会議</strong></span>［1889］ ……中南米進出の口実が「<strong class=\"source-bold\">パン＝アメリカ主義</strong>」</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> アメリカ政府による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フロンティア消滅宣言</strong></span>［1890］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span> 以後、対外進出</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マッキンリー</strong></span>大統領<strong class=\"source-bold\">《共和党》</strong>［任1897〜1901］</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>米西<rt>べいせい</rt></ruby>戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ＝スペイン戦争</strong></span>】</strong>［1898］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">キューバの独立運動支援</strong>が口実</p>\n<p>……キューバの独立指導者：<strong class=\"source-bold\">ホセ＝マルティ</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">メーン号爆沈事件</strong>を機にアメリカがスペインと開戦 <span data-source-color=\"green\" style=\"color:#315837\">➡</span> <strong class=\"source-bold\">アメリカの勝利</strong></p>\n<p>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>［1898］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバの独立</strong></span> <span data-source-color=\"green\" style=\"color:#315837\">➡</span> のちに<strong class=\"source-bold\">プラット条項</strong>によって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ保護国化</strong></span>［1901］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グアム</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プエルトリコ</strong></span>をアメリカに<ruby>割譲<rt>かつじょう</rt></ruby></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ<ruby>併合<rt>へいごう</rt></ruby></strong></span>［1898］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span> <strong class=\"source-bold\">太平洋航路の確保</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby>宣言</strong></span>［1899／1900］ ……国務長官<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ヘイ</strong></span>が提唱</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> 中国に関して、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">門戸開放・機会均等</strong></span>」［1899］「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">領土<ruby>保全<rt>ほぜん</rt></ruby></strong></span>」［1900］を宣言</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セオドア＝ローズヴェルト</strong></span> <strong class=\"source-bold\">《共和党》</strong>大統領［任1901〜1909］</p>\n<blockquote><p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カリブ海政策</strong></span>＝「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>棍棒<rt>こんぼう</rt></ruby>外交</strong></span>」（軍事力を背景とする外交政策）</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">ドミニカ</strong>を事実上保護国化［1905］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span> 1916年から軍政下に置く</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パナマ運河</strong></span>の建設［1904着工／1914完成］</p>\n<p><strong class=\"source-bold\">コロンビアからパナマを独立</strong>させ、運河の<strong class=\"source-bold\">工事権・永久<ruby>租借<rt>そしゃく</rt></ruby>権</strong>を獲得</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> アジア方面……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーツマス条約</strong></span>（<ruby>日露<rt>にちろ</rt></ruby>戦争の<ruby>講和<rt>こうわ</rt></ruby>条約）の調停［1905］</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">マッキンリーの<ruby>砲艦<rt>ほうかん</rt></ruby>外交。キューバを狙って米西戦争が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p>1897年に就任した<strong class=\"source-bold\">共和党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マッキンリー</strong></span>大統領は、<strong class=\"source-bold\">積極的な帝国主義政策</strong>を進めたよ。狙うのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ</strong></span>だ！ <strong class=\"source-bold\">スペイン領のキューバ</strong>で<strong class=\"source-bold\">ホセ＝マルティ</strong>による独立運動が起こると、アメリカでは<strong class=\"source-bold\">キューバ独立を支持する世論が高まった</strong>。このウラには、<strong class=\"source-bold\">キューバのサトウキビ産業に投資していたアメリカ企業</strong>が、「独立したほうがもっと儲けられるぜ」って思っていたこともあるんだけどさ。</p>\n<p>そして、<strong class=\"source-bold\">マッキンリー</strong>はすでにキューバを取る気で、世論が盛り上がる前に<strong class=\"source-bold\">戦争準備を始めていた</strong>。軍艦と<ruby>大砲<rt>たいほう</rt></ruby>でぶっ飛ばすから「<strong class=\"source-bold\">砲艦外交</strong>」だ。そして、世論に乗っかって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバの独立支援</strong></span>を口実に戦争を起こしたんだよ。</p>\n<p>1898年、キューバのハバナ港で起きたアメリカ軍艦<strong class=\"source-bold\">メーン号爆沈事件</strong>をきっかけに、<strong class=\"source-bold\">アメリカがスペインに<ruby>宣戦<rt>せんせん</rt></ruby></strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米西戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ＝スペイン戦争</strong></span>】</strong>が始まる</p>",
  "231": "<h2>231</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国 ～アメリカの帝国主義～</u></p>\n<p>と、<strong class=\"source-bold\">アメリカ海軍は一気にスペイン海軍を破った</strong>。しかも同時に、地球の裏側の<strong class=\"source-bold\">フィリピンにもアメリカ軍が<ruby>侵入<rt>しんにゅう</rt></ruby></strong>、たちまちフィリピンを<ruby>占領<rt>せんりょう</rt></ruby>した。準備よすぎるだろ。</p>\n<p>こうして<strong class=\"source-bold\">アメリカが一方的に勝利</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>が結ばれ、アメリカは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グアム</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プエルトリコ</strong></span>を獲得したよ。もちろんスペインには<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ独立</strong></span>を認めさせた。そうはいっても、アメリカがそのままキューバを独立させるわけないよ……。1901年、アメリカはキューバの憲法に<strong class=\"source-bold\">プラット条項</strong>を無理やりぶち込んで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバを保護国化</strong></span>すると、<strong class=\"source-bold\">グアンタナモにアメリカ海軍の基地を建設</strong>した。やってることが、ひどすぎるよ……。</p>\n<blockquote><p>アメリカがらみの条約の名前は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>」が多いね。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">七年戦争</strong></span>後の英仏の条約、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ独立戦争</strong></span>後の米英の条約もパリ条約だよ</p></blockquote>\n<h4><strong class=\"source-bold\">〈アメリカの帝国主義〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">門戸開放宣言</span></td><td>フィリピン</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">太平洋航路の確保</span></td><td>ハワイ<br>グアム</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">カリブ海政策</span></td><td><strong class=\"source-bold\">アメリカ合衆国</strong><br><strong class=\"source-bold\">キューバ</strong><br><strong class=\"source-bold\">プエルトリコ</strong><br><strong class=\"source-bold\">ドミニカ</strong><br>パナマ運河</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">いよいよアジア進出の開始！……と思ったら、中国分割が終わってた</strong></span></h4>\n<p><strong class=\"source-bold\">米西戦争</strong>で<strong class=\"source-bold\">フィリピンとグアム</strong>を取っただけじゃなくて、アメリカは着々と<strong class=\"source-bold\">太平洋に進出</strong>する準備を進めてたんだよ。1893年、<strong class=\"source-bold\">親米市民のクーデタ</strong>によって、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ</strong></span>の<strong class=\"source-bold\">カメハメハ朝</strong>の女王<strong class=\"source-bold\">リリウオカラニ</strong>を退位させていたアメリカは、<strong class=\"source-bold\">米西戦争中</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ併合</strong></span>を強行したんだ。しかも、すでに<strong class=\"source-bold\">ペリーの<ruby>艦隊<rt>かんたい</rt></ruby></strong>によって<strong class=\"source-bold\">日本の開国</strong>（<strong class=\"source-bold\">日米<ruby>和親<rt>わしん</rt></ruby>条約</strong>［1854］の<ruby>締結<rt>ていけつ</rt></ruby>ね）にも成功し、1858年には<strong class=\"source-bold\">日米<ruby>修好<rt>しゅうこう</rt></ruby>通商条約</strong>を結んだから、<strong class=\"source-bold\"><ruby>箱館<rt>はこだて</rt></ruby>（函館）、神奈川（横浜）、兵庫（神戸）、新潟、長崎</strong>への入港がで</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "232": "<h2>232</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p>きる。こうして<strong class=\"source-bold\">太平洋航路を確保</strong>したアメリカは、いよいよ<strong class=\"source-bold\">本格的にアジア進出</strong>（<strong class=\"source-bold\">おもに貿易</strong>だよ）を始めたかったんだけど……いきなり問題にぶち当たった。</p>\n<p>独立を求めるフィリピンとの間で<strong class=\"source-bold\">フィリピン＝アメリカ戦争</strong>が起こり、さらに<ruby>米西<rt>べいせい</rt></ruby>戦争が終わった1898年には、ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>と日本による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国分割</strong></span>がほぼ完了していた。<strong class=\"source-bold\">アメリカは中国進出には完全に出遅れた</strong>ってわけだ。そこで、マッキンリー政権の<strong class=\"source-bold\">国務長官<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ヘイ</strong></span></strong>は、1899年と1900年の2回にわたって、<strong class=\"source-bold\">列強に対して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby>宣言</strong></span></strong>を発表したよ。まず1899年に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">門戸開放</strong></span>」「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">機会均等</strong></span>」を、そして1900年に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">領土<ruby>保全<rt>ほぜん</rt></ruby></strong></span>」を提唱した。これって要するに「アメリカも中国<ruby>市場<rt>しじょう</rt></ruby>に割り込みたい！ オレにも<ruby>儲<rt>もう</rt></ruby>けさせろ！」ってことだね。そして、<strong class=\"source-bold\">「門戸開放・機会均等・領土保全」</strong>の3原則が、第二次世界大戦まで<strong class=\"source-bold\">アメリカのアジア外交の基本原則</strong>になるんだよ。ここは、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第10回</strong></span>の中国分割のところとあわせて確認してね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">キューバだけでは終わらない！ カリブ海諸国への「<ruby>棍棒<rt>こんぼう</rt></ruby>外交」</strong></span></h4>\n<p><strong class=\"source-bold\">マッキンリー大統領の暗殺後</strong>、副大統領から昇格した<strong class=\"source-bold\">セオドア＝ローズヴェルト</strong>大統領はマッキンリーが進めていた<strong class=\"source-bold\">カリブ海への進出</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カリブ海政策</strong></span>）と<strong class=\"source-bold\">アジア進出</strong>を引き継いだ。まずは<strong class=\"source-bold\">カリブ海政策</strong>から見ていこう。</p>\n<p><strong class=\"source-bold\">セオドア＝ローズヴェルト</strong>は、<strong class=\"source-bold\">カリブ海政策の口実</strong>として「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンロー宣言</strong></span>」を持ち出したよ。「モンロー宣言」って、本来は「アメリカ大陸とヨーロッパの相互<ruby>不干渉<rt>ふかんしょう</rt></ruby>」だけど、これを「<strong class=\"source-bold\">ヨーロッパはラテンアメリカにきちゃダメだけど、アメリカはラテンアメリカに進出してもいい</strong>」っていうふうに拡大解釈した。だって、アメリカ合衆国とラテンアメリカは両方とも「アメリカ大陸」でしょ？ 「<strong class=\"source-bold\">パン＝アメリカ主義</strong>」と組み合わせれば、アメリカはいくらでもラテンアメリカ進出してもいい、って<strong class=\"source-bold\">カリブ海政策を正当化</strong>できる。……ヘリクツだと思ったでしょ？</p>\n<p>では、もう一度アメリカの外交戦略を確認！ <strong class=\"source-bold\">ヨーロッパ</strong>に対しては、<strong class=\"source-bold\">モンロー宣言に基づく「孤立主義」</strong>（ヨーロッパからの孤立）、<strong class=\"source-bold\">ラテンアメリカ</strong>に対しては「<strong class=\"source-bold\">パン＝アメリカ主義</strong>」、これを組み合わせてラテンアメリカに進出する。そして、ラテンアメリカ諸国が文句を言いそうな時は「何かあったら軍隊出すぞ！」って<strong class=\"source-bold\">武力をちらつかせてビビらせ、アメリカの影響下に置く</strong>んだ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">棍棒外交</strong></span>」だよ。</p>\n<p>じゃあ、「棍棒」で何をするのかっていうと、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パナマ運河</strong></span>を建設したかったんだよ。<strong class=\"source-bold\">アメリカ</strong>って大陸国家だけど、<strong class=\"source-bold\">実は海洋国家</strong>だよね。<strong class=\"source-bold\">大西洋と太平洋に挟まれてる</strong>でしょ。だから、海軍も両方に置いとかなきゃいけない。でも困ったことがあるんだ。<strong class=\"source-bold\">大西洋と太平洋の間で軍艦を行き来させるためには、南米の南端を回らなきゃいけない</strong>んだよ。しかも、首都ワシントン（つまり東海岸）からアジアに行くとする</p>\n<blockquote><p>「大きな棍棒を持って、おだやかに話せ」ってのがローズヴェルトの言葉だ。全然おだやかじゃないね</p></blockquote>",
  "233": "<h2>233</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国 ～アメリカの帝国主義～</u></p>\n<p>と、大西洋を横断してスエズ運河を経由したほうが早かったりする……。しかも、ドイツや日本も海軍を増強してるし……。海洋国家として、大西洋と太平洋の両方を守るために、どうしても<strong class=\"source-bold\">パナマ運河がほしかった</strong>んだよ。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セオドア＝ローズヴェルト</strong></span>は、<strong class=\"source-bold\">パナマ地峡を支配しているコロンビア</strong>に「運河を掘らせろ！」って言ったら断られた。当たり前だよ、「はいどうぞ」なんて言うわけがない。そこで運河を掘りたいところに<strong class=\"source-bold\">アメリカ人を移住</strong>させて<strong class=\"source-bold\">独立運動</strong>をやらせ、それを支援して<strong class=\"source-bold\">パナマ共和国</strong>を独立させた。そして、パナマ共和国に「運河を掘りたいから、運河予定地の<strong class=\"source-bold\">永久<ruby>租借<rt>そしゃく</rt></ruby>権</strong>と<strong class=\"source-bold\">工事権</strong>をよこせ！」って言って奪い、ちゃっかり<strong class=\"source-bold\">工事を始めた</strong>んだよ。なんだよこの自作自演。覚えてるかな？ <strong class=\"source-bold\">テキサス<ruby>併合<rt>へいごう</rt></ruby>と同じ手口</strong>だ。ちなみに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パナマ運河</strong></span>の<strong class=\"source-bold\">完成</strong>は1914年、<strong class=\"source-bold\">第一次世界大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby>の年</strong>だよ。</p>\n<p>その後もアメリカは、対外<ruby>債務<rt>さいむ</rt></ruby>を返せない国の財政をアメリカの銀行に乗っ取らせて保護国化したり、政治に干渉したりを繰り返した。1905年には<strong class=\"source-bold\">ドミニカ</strong>から関税管理権を奪って事実上の保護国にしたり、さらに<strong class=\"source-bold\">ニカラグア</strong>や<strong class=\"source-bold\">ハイチ</strong>もたびたびアメリカの干渉を受けたよ。</p>\n<p>一方、アジア外交では<ruby>日露<rt>にちろ</rt></ruby>戦争後の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーツマス条約</strong></span><ruby>締結<rt>ていけつ</rt></ruby>を<ruby>仲介<rt>ちゅうかい</rt></ruby>するなど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">門戸開放宣言</strong></span>に基づく勢力均衡を図った。特に「領土保全」をしない国は、アメリカの敵ってことになるから、20世紀の初めだと、<strong class=\"source-bold\">満洲<ruby>占領<rt>せんりょう</rt></ruby>をしていたロシア</strong>が敵ってことになるよね。だから<strong class=\"source-bold\">日露戦争では日本寄り</strong>となって、<ruby>講和<rt>こうわ</rt></ruby>の仲介をしたんだ。</p>\n<blockquote><p>陸上の大陸横断鉄道と海運のパナマ運河。アメリカの東西を結ぶ重要な交通だよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「棍棒外交」の次は、経済を乗っ取る「ドル外交」だ！</strong></span></h4>\n<p>セオドア＝ローズヴェルトの次に大統領になったのが、<strong class=\"source-bold\">共和党のタフト</strong>だよ。アメリカはこれまで、<strong class=\"source-bold\">武力で脅かしながらラテンアメリカを影響下に置く「棍棒外交」</strong>を展開していたけど、<strong class=\"source-bold\">タフトの時代には少しだけ方針が変わった</strong>んだ。とはいっても「ラテンアメリカをアメリカの影響下に置いとこう」ってのは変わらない。やり方がちょっと変わって「アメリカ資本がラテンアメリカに進出して、<strong class=\"source-bold\">投資の拡大によって政治的・経済的な影響力を強くしよう！</strong>」っていう、簡単に言うと札束でぶっ飛ばす「<strong class=\"source-bold\">ドル外交</strong>」になったんだよ。弾丸でぶっ飛ばすか、ドルでぶっ飛ばすか。まあ、どっちにしてもぶっ飛ばすんだけど。ただ、<strong class=\"source-bold\">アメリカに対する反乱が起きたら、どっちにしても軍隊を出す</strong>んだよ。例えば、<strong class=\"source-bold\">ニカラグア</strong>には海兵隊を派遣したしね。</p>\n<p>そして、第一次世界大戦の直前には、ひさびさに<strong class=\"source-bold\">民主党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>が大統領になったよ。ウィルソンはかなりの理想主義者だったから、アメリカを「<strong class=\"source-bold\">世界一自由</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "234": "<h2>234</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第12回</strong></span> 帝国主義時代の欧米諸国</p>\n<p><strong class=\"source-bold\">な民主主義の国</strong>」として、「<strong class=\"source-bold\">ラテンアメリカの<ruby>独裁<rt>どくさい</rt></ruby>政治を民主主義・資本主義体制に変えるのがアメリカの使命だ！</strong>」って考える「<strong class=\"source-bold\"><ruby>宣教師<rt>せんきょうし</rt></ruby>外交</strong>」を展開したよ。アメリカが自由と民主主義の「宣教師」ってことね。だから、アメリカの民主主義に従わない国には軍隊を送るし、アメリカと同じ資本主義に変えるためにアメリカ資本を進出させるから、ハイチやドミニカ、キューバには海兵隊を送ったし、<strong class=\"source-bold\">メキシコ革命にも<ruby>干渉<rt>かんしょう</rt></ruby></strong>した。なんだよ！ <strong class=\"source-bold\">やってることは「<ruby>棍棒<rt>こんぼう</rt></ruby>外交」や「ドル外交」と同じ</strong>じゃないか。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">メキシコでは、ラテンアメリカ初の民主主義革命が起こった！</strong></span></h4>\n<p>んじゃ、続いて<strong class=\"source-bold\">メキシコ</strong>について見ていくよ。メキシコは独立戦争で農業が大きな被害を受け、鉱山も操業停止に追い込まれて、経済はガタガタだったんだ。さらに<strong class=\"source-bold\">アメリカ＝メキシコ戦争で負けて、広大な領土を奪われた</strong>。</p>\n<p>しかし、みんなが国家を再建したいって思っているのに、保守派（保守党）と革新派（自由党）が対立したんだ。1858年に革新派で<strong class=\"source-bold\">インディオ出身</strong>の<strong class=\"source-bold\">フアレス</strong>大統領が誕生して<strong class=\"source-bold\">レフォルマ【大改革】</strong>を開始し、<strong class=\"source-bold\">教会や軍部の特権廃止、土地改革</strong>などの自由主義的な改革（レフォルマ法）を進めると、保守派との間で<strong class=\"source-bold\">内戦が<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>した。このレフォルマの内戦を見た<strong class=\"source-bold\">フランス皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナポレオン3世</strong></span></strong>は「今が中南米に進出するチャンス」とばかりに<strong class=\"source-bold\">イギリス・スペイン</strong>を誘い、メキシコの対外<ruby>債務<rt>さいむ</rt></ruby>不払いを口実に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">メキシコに出兵</strong></span>し、オーストリアの皇族<strong class=\"source-bold\">マクシミリアン</strong>を帝位に<ruby>就<rt>つ</rt></ruby>けたんだ。同じころに<strong class=\"source-bold\">アメリカでは南北戦争が起きていた</strong>から、その隙をついた出兵だね。しかし、南北戦争が終わると<strong class=\"source-bold\">アメリカがモンロー宣言を使って抗議</strong>してきたから<strong class=\"source-bold\">フランスは撤退</strong>することになった。そして、メキシコのフアレス大統領は<strong class=\"source-bold\">マクシミリアンを処刑して、勝利を収めた</strong>んだ。</p>\n<p>その後メキシコでは、フランスとの戦いで活躍した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディアス</strong></span>将軍がクーデタで大統領となり、教会や軍部、大地主の特権を復活させて<strong class=\"source-bold\">独裁を強化</strong>し、<strong class=\"source-bold\">経済的にはアメリカと結んで権力を維持</strong>した。こうしてメキシコは、<strong class=\"source-bold\">アメリカへの従属</strong>を強めてしまったんだね。ディアスの独裁は工場の建設や鉄道の開通などの近代化をもたらしたけど、産業は外国資本の支配下に置かれ、土地を奪われた多くの農民は貧困に苦しみ、下層労働者の生活もひどいままだったから、だんだんと<strong class=\"source-bold\">独裁政権への批判が高まり</strong>、政権を倒す動きが起きたんだ。</p>\n<p>1910年、<strong class=\"source-bold\">自由主義者で地主</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マデロ</strong></span>や<strong class=\"source-bold\">農民</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サパタ</strong></span>を指導者とする革命が起きると、<strong class=\"source-bold\">ディアスが追放</strong>されて<strong class=\"source-bold\">マデロが大統領</strong>になったよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">メキシコ革命</strong></span>の始まりだ。ただ、ディアスの独裁は倒したものの、その後の政</p>\n<blockquote><p>ディアスを倒したあとも、農民たちが求める土地改革は、なかなか実現しないんだよ</p></blockquote>",
  "235": "<h2>235</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国 ～アメリカの帝国主義～</u></p>\n<p>府をどうするかっていう合意がなくて、<strong class=\"source-bold\">地主のマデロ大統領と農民のサパタが対立</strong>し、サパタが農民を率いて反乱を起こしたもんだから、政権はいきなり危機になった。</p>\n<p>そして、反乱の<ruby>鎮圧<rt>ちんあつ</rt></ruby>を命じられた軍部の<strong class=\"source-bold\">ウェルタ</strong>将軍は、反乱側と裏取引をして<strong class=\"source-bold\">クーデタを起こし、マデロ大統領を捕えて殺害</strong>すると、政権に就いた。しかし、このクーデタに反対する憲政派（<strong class=\"source-bold\">カランサ</strong>が指導する<strong class=\"source-bold\">中産階級</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サパタ</strong></span>や<strong class=\"source-bold\">ビリャ</strong>が指導する<strong class=\"source-bold\">農民勢力</strong>が団結したよ）がウェルタ政権に反対して、<strong class=\"source-bold\">メキシコは内戦</strong>になっちゃった。この時、<strong class=\"source-bold\">アメリカ大統領ウィルソン</strong>は、ウェルタを「殺人者」と呼んで承認せず、<strong class=\"source-bold\">海兵隊を派遣して干渉</strong>すると、<strong class=\"source-bold\">ウェルタ政権は崩壊</strong>した。</p>\n<p>こうして<strong class=\"source-bold\">カランサが政権に就いた</strong>んだけど、「改革が甘い！」と主張する<strong class=\"source-bold\">農民勢力</strong>（サパタ派、ビリャ派）<strong class=\"source-bold\">が反対</strong>してメキシコの混乱は続き、最終的には1917年に<strong class=\"source-bold\">民主的な憲法</strong>が制定されて、<strong class=\"source-bold\">カランサ</strong>が<strong class=\"source-bold\">正式な大統領</strong>となったよ。ただ、このあともメキシコでは混乱が続くんだよね。サパタもビリャも、ついでにカランサも暗殺されたし。その後、1934年に<ruby>就任<rt>しゅうにん</rt></ruby>した<strong class=\"source-bold\">カルデナス</strong>大統領の時代に、教育の普及や労働者保護、<strong class=\"source-bold\">農地改革、石油国有化</strong>などの<strong class=\"source-bold\">民主的な改革</strong>が進むことになるよ。あっ、難関大の正誤問題の選択肢で出てきたりするから、<strong class=\"source-bold\">メキシコの石油国有化</strong>は「<strong class=\"source-bold\">第二次世界大戦前</strong>」っておさえておいてね。</p>\n<p>今回は盛りだくさんだけど、<ruby>頑張<rt>がんば</rt></ruby>って復習してね。</p>\n<p>それじゃあ最後に年号 check しよう！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">‼</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">年号</span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">イギリス、第3回選挙法改正</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">884</strong></span>］（選挙権やるから <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>は<rt>8</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>し<rt>4</rt></ruby></strong></span>たてるな）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ブーランジェ事件</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1887</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>ん<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>な<rt>7</rt></ruby></strong></span>きゃ 軍事独裁）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ドレフュス事件</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">894</strong></span>］（終身刑は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>白<rt>89</rt></ruby><ruby>紙<rt>4</rt></ruby></strong></span>にもどせ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\">ビスマルク退陣（ヴィルヘルム2世の親政開始）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1890</strong></span>］</p>\n<p>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>違<rt>1</rt></ruby><ruby>約<rt>89</rt></ruby><ruby>を<rt>0</rt></ruby></strong></span>責められ ビスマルク退陣）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\"><ruby>露仏<rt>ろふつ</rt></ruby>同盟の成立</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1891</strong></span>］（露仏が組めば <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>躍<rt>89</rt></ruby><ruby>1<rt>1</rt></ruby></strong></span>位だ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <strong class=\"source-bold\"><ruby>米西<rt>べいせい</rt></ruby>戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1898</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>発<rt>8</rt></ruby><ruby>キュー<rt>9</rt></ruby><ruby>バ<rt>8</rt></ruby></strong></span>へ 米西戦争）</p>\n<p>次回はいよいよ<strong class=\"source-bold\">第一次世界大戦</strong>だよ。<strong class=\"source-bold\">第一次世界大戦までの国際関係</strong>では、これまでやってきたことが次々と出てくるから、ここまでで不安なところはもう一度見直しておこう。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>"
};

